"""Core data models — the contract between the agent and consuming products."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal
from datetime import UTC, datetime
import uuid


# ──────────────────────────────────────────────
# Input
# ──────────────────────────────────────────────

@dataclass
class ResearchInput:
    """What the user sends to kick off a research run."""
    query: str
    input_type: Literal["keywords", "youtube_url", "newsletter_url", "freeform"] = "freeform"
    user_id: str = "default"
    context: dict = field(default_factory=dict)
    output_mode: str = "research_report"
    product: str = "research_report"
    lens_preferences: list[str] | None = None


@dataclass
class ResearchConfig:
    """Per-run config overrides."""
    cost_ceiling: float = 3.0
    timeout_seconds: int = 300
    lens_preferences: list[str] | None = None
    skip_platforms: list[str] = field(default_factory=list)


# ──────────────────────────────────────────────
# Source References
# ──────────────────────────────────────────────

@dataclass
class SourceRef:
    """A single source found during research."""
    title: str
    url: str
    snippet: str
    platform: Literal["web", "reddit", "youtube", "hackernews", "paa", "supadata"]
    engagement: dict = field(default_factory=dict)
    freshness_days: int = 0
    relevance_score: float = 0.0
    source_agent: str = ""


# ──────────────────────────────────────────────
# Comment Mining
# ──────────────────────────────────────────────

@dataclass
class CommentCluster:
    """A cluster of thematically similar comments from audience mining."""
    theme: str
    representative_comments: list[str] = field(default_factory=list)
    frequency: int = 0
    sentiment: float = 0.0
    unmet_ask: bool = False
    source_platform: str = ""


# ──────────────────────────────────────────────
# Supply-Side
# ──────────────────────────────────────────────

@dataclass
class ContentItem:
    """An existing piece of content found in supply-side analysis."""
    title: str
    url: str
    views: int = 0
    likes: int = 0
    comments_count: int = 0
    published_date: str = ""
    channel_id: str = ""
    channel_title: str = ""
    channel_subscribers: int = 0
    duration_seconds: int = 0
    engagement_ratio: float = 0.0
    sentiment_score: float = 0.0


@dataclass
class Gap:
    """A gap identified in existing content supply."""
    gap_type: Literal["recency", "format", "depth", "sentiment"]
    confidence: float = 0.0
    evidence_urls: list[str] = field(default_factory=list)
    description: str = ""


@dataclass
class SupplySideReport:
    """Complete supply-side analysis for a topic."""
    top_content: list[ContentItem] = field(default_factory=list)
    gaps: list[Gap] = field(default_factory=list)
    overall_saturation: float = 0.0


# ──────────────────────────────────────────────
# Thesis
# ──────────────────────────────────────────────

@dataclass
class Thesis:
    """A thesis generated by one of the 4 lens agents."""
    lens: Literal["strategy", "signal", "execution", "contrarian"]
    statement: str = ""
    supporting_points: list[str] = field(default_factory=list)
    supply_side_rationale: str = ""
    score: float = 0.0
    rejection_reason: str | None = None


# ──────────────────────────────────────────────
# Cost
# ──────────────────────────────────────────────

@dataclass
class CostBreakdown:
    """Per-run cost tracking."""
    run_id: str = ""
    layer_costs: dict[str, float] = field(default_factory=dict)
    tool_costs: dict[str, float] = field(default_factory=dict)
    model_costs: dict[str, float] = field(default_factory=dict)
    total: float = 0.0
    duration_seconds: float = 0.0

    def add_cost(self, layer: str, tool: str, model: str, amount: float):
        self.layer_costs[layer] = self.layer_costs.get(layer, 0) + amount
        self.tool_costs[tool] = self.tool_costs.get(tool, 0) + amount
        self.model_costs[model] = self.model_costs.get(model, 0) + amount
        self.total += amount


# ──────────────────────────────────────────────
# Final Result (THE CONTRACT)
# ──────────────────────────────────────────────

@dataclass
class ResearchResult:
    """The unified output — both products consume this."""
    winning_thesis: Thesis | None = None
    rejected_candidates: list[Thesis] = field(default_factory=list)
    sources: list[SourceRef] = field(default_factory=list)
    supply_side_report: SupplySideReport = field(default_factory=SupplySideReport)
    unmet_asks: list[CommentCluster] = field(default_factory=list)
    cost_breakdown: CostBreakdown = field(default_factory=CostBreakdown)
    score_breakdown: dict = field(default_factory=dict)
    verification_notes: list[dict] = field(default_factory=list)
    adapted_output: dict = field(default_factory=dict)
    raw_data: dict = field(default_factory=dict)
    shadow_comparison: dict = field(default_factory=dict)
    run_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    started_at: str = field(default_factory=lambda: datetime.now(UTC).isoformat())
    completed_at: str = ""
    status: Literal["pending", "running", "complete", "rejected", "error"] = "pending"
    rejection_reason: str | None = None
    error: str | None = None


# ──────────────────────────────────────────────
# WebSocket Events
# ──────────────────────────────────────────────

@dataclass
class AgentEvent:
    """Real-time event streamed to the UI via WebSocket."""
    event: Literal["layer_start", "layer_complete", "agent_start", "agent_complete", "agent_error", "result", "error"]
    layer: str = ""
    agent: str = ""
    status: str = ""
    message: str = ""
    data: dict = field(default_factory=dict)
    timestamp: str = field(default_factory=lambda: datetime.now(UTC).isoformat())

    def to_dict(self) -> dict:
        return {
            "event": self.event,
            "layer": self.layer,
            "agent": self.agent,
            "status": self.status,
            "message": self.message,
            "data": self.data,
            "timestamp": self.timestamp,
        }
